<script setup lang="ts">
import {computed} from 'vue'
import {rowData,rowsOf,type BusinessData} from '@/api/modules/business'
import {acceptanceSummary,sixLabels,sixStates} from '@/business/contractSix'
import {display} from '@/business/labels'
import BusinessDetails from './BusinessDetails.vue'
const props=defineProps<{record:BusinessData;domain:string;section?:string}>()
const d=computed(()=>rowData(props.record))
const acceptance=computed(()=>['stock','auditions'].includes(props.domain)?acceptanceSummary(props.record,props.domain as 'stock'|'auditions'):null)
const link=computed(()=>props.record.kind==='LINK'?props.record.id:props.record.parent_id||props.record.link_id)
const request=computed(()=>(props.record.request||{}) as BusinessData)
const closureId=computed(()=>props.record.request_id||props.record.id)
const closure=computed(()=>props.domain==='privacy'&&typeof props.record.response_due_on==='string'&&typeof props.record.status==='string')
const quote=computed(()=>(d.value.quote||d.value) as BusinessData)
const referral=computed(()=>(quote.value.referral||d.value.attribution||{}) as BusinessData)
const referralRule=computed(()=>((referral.value.rule_snapshot as BusinessData|undefined)?.data as BusinessData|undefined)?.rule as BusinessData|undefined||d.value.rule as BusinessData|undefined)
const states=(v:unknown)=>sixStates[String(v)]||display(v)
</script>
<template>
 <section v-if="acceptance&&acceptance.hours!==null" class="supply-card" data-testid="contract-acceptance-facts"><h3>本单验收起点与截止</h3><dl class="supply-facts"><div><dt>采用规则</dt><dd>{{acceptance.policy}}</dd></div><div><dt>何时起算</dt><dd>{{acceptance.start}}</dd></div><div><dt>原约定时长</dt><dd>{{acceptance.hours}} 小时</dd></div><div><dt>服务器已记录起点</dt><dd>{{acceptance.startedAt?display(acceptance.startedAt):'尚未记录；不在客户端创建倒计时'}}</dd></div><div><dt>服务器已记录截止</dt><dd>{{acceptance.deadline?display(acceptance.deadline):'尚未记录，以原单后续核验为准'}}</dd></div></dl><p>{{acceptance.warning}}</p></section>
 <section v-if="domain==='handover'&&record.relation_id" class="supply-card" data-testid="handover-facts"><h3>原机构关系的7日交接</h3><p>开始：{{display(record.started_at)}}；截止：{{display(record.deadline_at)}}；当前{{states(record.period_status)}}。</p><p>仅捕获的旧订单可按仍有效授权继续沟通。双方确认、到期或撤权后停止；逾期补记不恢复权限，旧收入及合同不改写。</p><RouterLink :to="`/gigs/relations/${record.relation_id}`">返回原机构关系</RouterLink><article v-for="order in rowsOf(record)" :key="String(order.order_id)" class="supply-card" data-testid="handover-order-facts"><h4><RouterLink :to="`/trade/orders/${order.order_id}`">原订单 {{order.order_id}}</RouterLink></h4><p>交接：{{states(order.status)}}；原订单：{{states(order.order_status)}}。</p><p v-if="order.status==='ACKNOWLEDGED'">双方已确认，本笔旧单的机构沟通权限已停止。旧合同与结算仍保留。</p><p v-else-if="record.period_status==='EXPIRED'">交接期已届满，机构沟通权限已停止；可以补记交接，不恢复权限。</p><p v-else>尚待双方确认；能否继续沟通还须核对本人授权是否仍有效。</p><BusinessDetails :value="{acknowledgements:order.acknowledgements}" :field-labels="sixLabels"/></article></section>
 <section v-if="domain==='guardians'" class="supply-card" data-testid="guardian-facts"><h3>监护办理与实际结果</h3><p>关系确认、独立审核、使用限制、消费同意和实际退款分别记录。真实儿童采集及收费保持关闭。</p><p v-if="d.controls">{{(d.controls as BusinessData).enabled?'当前在已审核限制内允许使用':'监护人已关闭使用，已有使用时段失效'}}。</p><p v-if="record.kind==='SPEND'">本次仅记录监护同意，不代表已经付款或可调用真实支付。</p><p v-if="record.kind==='REFUND'">原支付退款状态：{{d.actual_refund_status?states(d.actual_refund_status):'尚无实际退款结果'}}。申请提交、审核通过或进入退款流程均不代表资金已退回。</p><p v-if="record.kind==='INFORMATION'">信息处理实际进度：{{d.actual_privacy_status?states(d.actual_privacy_status):'待工作人员处理'}}。提出申请不代表资料已经删除或账号已注销。</p><div v-if="link" class="supply-actions"><RouterLink :to="`/guardians/records/${link}`">原监护关系与限制</RouterLink><RouterLink :to="`/guardians/usage/${link}`">使用与休息提醒</RouterLink><RouterLink :to="`/guardians/content/${link}`">已审核适龄预览</RouterLink><RouterLink :to="`/guardians/information/${link}`">监护人查询必要目录</RouterLink></div><p v-if="record.rest_reminder_minutes">休息提醒：每{{record.rest_reminder_minutes}}分钟；已预留{{record.seconds_reserved}}秒。时段到期需明确申请下一分钟，不自动反复续时。</p></section>
 <section v-if="domain==='privacy'&&(request.type==='CLOSE_ACCOUNT'||closure)" class="supply-card" data-testid="closure-clock-facts"><h3>回复期限与注销执行期限</h3><p>收到申请后的回复目标：{{display(record.response_due_on)}}。</p><template v-if="closure"><p>{{states(record.status)}}</p><p v-if="!record.verified_at">尚未独立核验通过，不显示虚假的15工作日执行倒计时。</p><template v-else><p>核验通过：{{display(record.verified_at)}}；原执行截止：{{display(record.original_due_on)}}；当前执行截止：{{display(record.due_on)}}。</p><p>日期依据：{{record.calendar_version?'冻结的已审核工作日日历 '+record.calendar_version:'普通工作日估算，需核对完整日历'}}。</p></template><p v-if="record.completed_at">实际执行并独立复核后结案：{{display(record.completed_at)}}。</p><p v-else>只有实际账号关闭、执行任务及必要删除/保留事项核对后才能结案；答复申请不代表执行完成。</p><BusinessDetails v-if="record.extensions" :value="{extensions:record.extensions}" :field-labels="sixLabels"/></template><RouterLink v-if="!closure||section==='closure-queue'" :to="`/privacy/${['operations','closure-queue'].includes(section||'')?'closure-operations':'closure'}/${closureId}`">读取本申请的核验与执行期限</RouterLink></section>
 <section v-if="domain==='infringement'" class="supply-card" data-testid="infringement-facts"><h3>材料送达与内容限制</h3><p>24小时等响应时间是本案运营目标，不是法律自动裁决期限。联系人和内部意见不会自动转交。</p><p v-if="record.restriction_active===true">本案限制仍生效；申请撤回也须独立复核，不能直接恢复下载。</p><p v-else-if="record.restriction_active===false">本案当前无生效限制；其他案件、隐私及许可到期限制仍须逐项核验，不表示内容必然可下载。</p><p>已进入获准记录表示站内送达；接收方明确确认后才记录已读。</p><BusinessDetails v-if="record.deliveries" :value="{deliveries:record.deliveries}" :field-labels="sixLabels"/></section>
 <section v-if="referralRule?.referral_bps||referral.rate_bps!==undefined" class="supply-card" data-testid="referral-contract-facts"><h3>本版直接推荐约定</h3><p>规则：{{referralRule?.referral_contract_policy==='CONTRACT_20261029'?'2026-10-29新合同，四类直接推荐10%—15%':'原历史规则，按原快照保留'}}。</p><p v-if="typeof referral.rate_bps==='number'">本单冻结比例：{{referral.rate_bps/100}}%；归因状态：{{states(referral.status)}}。</p><BusinessDetails v-if="referralRule?.referral_bps" :value="{referral_bps:referralRule.referral_bps}" :field-labels="{...sixLabels,STOCK:'现货（基点）',AUDITION:'试镜（基点）',CUSTOMIZATION:'定制（基点）',COMMERCIAL:'商单（基点）'}"/><p>仅一级直接推荐，沿原7日归因和售后规则；历史5%不改成新比例，服务额度不重复叠加。</p></section>
</template>
